func newState() unsafe.Pointer { return unsafe.Pointer(new(managedfeatures.State)) }

func newNState(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]managedfeatures.State, n)))
}

func ptrState(p unsafe.Pointer, c int32) any {
	r := (*managedfeatures.State)(p)
	switch c {
	case 0:
		return &r.ScopeKey
	case 1:
		return (*string)(unsafe.Pointer(&r.ScopeBusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.Lifecycle))
	case 3:
		return &r.Features
	case 4:
		return &r.AddOnEndings
	case 5:
		return &r.PlanURL
	case 6:
		return &r.PlanEndsAt
	case 7:
		return &r.PlanEndAnnounced
	case 8:
		return &r.PlanEndReminded
	case 9:
		return (*int64)(unsafe.Pointer(&r.FinalBackupDays))
	case 10:
		return &r.ReceivedAt
	}
	return nil
}

func valueState(p unsafe.Pointer, c int32) any {
	r := (*managedfeatures.State)(p)
	switch c {
	case 0:
		return r.ScopeKey
	case 1:
		if r.ScopeBusinessUnitID == "" {
			return nil
		}
		return string(r.ScopeBusinessUnitID)
	case 2:
		return string(r.Lifecycle)
	case 3:
		if r.Features == nil {
			return keel.EmptyJSONArray
		}
		return r.Features
	case 4:
		if r.AddOnEndings == nil {
			return keel.EmptyJSONArray
		}
		return r.AddOnEndings
	case 5:
		if r.PlanURL == "" {
			return nil
		}
		return r.PlanURL
	case 6:
		if r.PlanEndsAt == 0 {
			return nil
		}
		return r.PlanEndsAt
	case 7:
		if r.PlanEndAnnounced == 0 {
			return nil
		}
		return r.PlanEndAnnounced
	case 8:
		if r.PlanEndReminded == 0 {
			return nil
		}
		return r.PlanEndReminded
	case 9:
		return int64(r.FinalBackupDays)
	case 10:
		return r.ReceivedAt
	}
	return nil
}

// intIs64 fails the build where int is not 64 bits: int fields are read through *int64.
const intIs64 = unsafe.Sizeof(int(0)) - 8

